import{buildIndex as l,live as p}from"./derive.min.js";export function contactLine(t){return t?t.title&&t.company?`${t.title} at ${t.company}`:t.title||t.company||"":""}export function peopleText(t){return t.length?t.length===1?t[0]:t.length===2?`${t[0]} and ${t[1]}`:`${t[0]}, ${t[1]} and ${t.length-2} more`:""}export function peopleOf(t,n,i=l(t)){return n.contactIds.map(o=>i.contactsById.get(o)).filter(Boolean)}export function linksOf(t,n,i=l(t)){const o=new Map,u=[];for(const e of t.applications)if(p(e)){e.contactIds.includes(n)&&o.set(e.id,e);for(const r of i.events(e.id))r.withContactIds.includes(n)&&(u.push(r),o.set(e.id,e))}return u.sort((e,r)=>(e.at||"").localeCompare(r.at||"")),{applications:[...o.values()],events:u}}export function involves(t,n,i){return t.contactIds.includes(n)?!0:i.events(t.id).some(o=>o.withContactIds.includes(n))}
